            if (!results) return null;
            if (results.goppar < 0) return window.mySimulation.t('hint_negative_gop');
            if (results.occupancy < 50) return window.mySimulation.t('hint_low_occupancy');
            if (results.walkedGuests > 0) return window.mySimulation.t('hint_walked_guests');
            if (results.compSetIndex < 85) return window.mySimulation.t('hint_below_compset');
            if (results.directPct < 15) return window.mySimulation.t('hint_low_direct');
            return null;
        }

